-- RIM AgroOvin Connect — Migration 002 : accès client et réservation contrôlée
-- Prérequis : migrations client V1.0/V1.1 et fonction rim_client_is_admin() déjà installées.

create table if not exists public.rim_client_accounts (user_id uuid primary key references auth.users(id) on delete cascade,status text not null default 'visitor' check(status in ('visitor','approved','suspended')),approved_at timestamptz,approved_by uuid references auth.users(id),updated_at timestamptz not null default now());
create table if not exists public.rim_client_access_requests (id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,full_name text not null,phone text not null,city text not null,address text,reason text,status text not null default 'pending' check(status in ('pending','approved','rejected')),admin_note text,reviewed_by uuid references auth.users(id),reviewed_at timestamptz,created_at timestamptz not null default now());
create index if not exists rim_client_requests_user_date on public.rim_client_access_requests(user_id,created_at desc);
create unique index if not exists rim_one_pending_client_request on public.rim_client_access_requests(user_id) where status='pending';

alter table public.rim_client_accounts enable row level security; alter table public.rim_client_access_requests enable row level security;
revoke all on public.rim_client_accounts from anon,authenticated; revoke all on public.rim_client_access_requests from anon,authenticated;
grant select on public.rim_client_accounts to authenticated; grant select,insert on public.rim_client_access_requests to authenticated;
drop policy if exists rim_client_account_read_self_admin on public.rim_client_accounts; create policy rim_client_account_read_self_admin on public.rim_client_accounts for select to authenticated using(user_id=auth.uid() or public.rim_client_is_admin());
drop policy if exists rim_client_request_read_self_admin on public.rim_client_access_requests; create policy rim_client_request_read_self_admin on public.rim_client_access_requests for select to authenticated using(user_id=auth.uid() or public.rim_client_is_admin());
drop policy if exists rim_client_request_insert_self on public.rim_client_access_requests; create policy rim_client_request_insert_self on public.rim_client_access_requests for insert to authenticated with check(user_id=auth.uid() and status='pending' and reviewed_by is null and reviewed_at is null and admin_note is null);

create or replace function public.rim_is_approved_client() returns boolean language sql stable security definer set search_path='' as $$ select exists(select 1 from public.rim_client_accounts a where a.user_id=auth.uid() and a.status='approved'); $$;
revoke all on function public.rim_is_approved_client() from public,anon; grant execute on function public.rim_is_approved_client() to authenticated;

create or replace function public.rim_decide_client_request(p_request_id uuid,p_decision text,p_admin_note text default null) returns void language plpgsql security definer set search_path='' as $$ declare v_user_id uuid; begin if not public.rim_client_is_admin() then raise exception 'Accès réservé aux administrateurs.'; end if; if p_decision not in ('approved','rejected') then raise exception 'Décision invalide.'; end if; select user_id into v_user_id from public.rim_client_access_requests where id=p_request_id and status='pending' for update; if v_user_id is null then raise exception 'Demande introuvable ou déjà traitée.'; end if; update public.rim_client_access_requests set status=p_decision,admin_note=p_admin_note,reviewed_by=auth.uid(),reviewed_at=now() where id=p_request_id; insert into public.rim_client_accounts(user_id,status,approved_at,approved_by,updated_at) values(v_user_id,case when p_decision='approved' then 'approved' else 'visitor' end,case when p_decision='approved' then now() else null end,case when p_decision='approved' then auth.uid() else null end,now()) on conflict(user_id) do update set status=excluded.status,approved_at=excluded.approved_at,approved_by=excluded.approved_by,updated_at=now(); end; $$;
revoke all on function public.rim_decide_client_request(uuid,text,text) from public,anon; grant execute on function public.rim_decide_client_request(uuid,text,text) to authenticated;

-- Un visiteur ou utilisateur non approuvé ne peut pas créer de réservation.
drop policy if exists rim_orders_insert_own on public.rim_client_orders; create policy rim_orders_insert_own on public.rim_client_orders for insert to authenticated with check(client_id=auth.uid() and status='pending' and public.rim_is_approved_client() and exists(select 1 from public.rim_livestock_animals a where a.id=animal_id and a.catalog_visible=true and a.status not in ('sold','dead') and a.public_price=price_snapshot));

-- L'approbation admin (status confirmed) retire l'animal du catalogue public.
create or replace function public.rim_sync_animal_catalog_on_order_status() returns trigger language plpgsql security definer set search_path='' as $$ begin if new.status in ('confirmed','preparing','ready','delivering','completed') then update public.rim_livestock_animals set catalog_visible=false where id=new.animal_id; elsif new.status in ('refused','cancelled') then update public.rim_livestock_animals set catalog_visible=true where id=new.animal_id and status not in ('sold','dead'); end if; return new; end; $$;
drop trigger if exists rim_order_catalog_visibility on public.rim_client_orders; create trigger rim_order_catalog_visibility after update of status on public.rim_client_orders for each row when(old.status is distinct from new.status) execute function public.rim_sync_animal_catalog_on_order_status();
